    {
        ThreadPool pool(4);
        for (int pct = -10; pct <= 10; ++pct) {
            results.push_back(pool.submit([pct] {  // long 1000 shares at 100, short 1000 calls at 105
                const double spot = 100.0 * (1.0 + pct / 100.0);
                return 1000.0 * (spot - 100.0) - 1000.0 * (spot > 105.0 ? spot - 105.0 : 0.0);
            }));
        }
    }  // the destructor runs every queued job, then joins the 4 threads
    std::cout << std::fixed << std::setprecision(2);
    for (int pct = -10; pct <= 10; pct += 5) {
        std::cout << "shock " << pct << "%: " << results[pct + 10].get() << '\n';
    }
    std::cout << results.size() << " scenarios on 4 threads\n";
    return 0;
}

