#include <cstddef>
#include <functional>
#include <future>
#include <iomanip>
#include <iostream>
#include <random>
#include <vector>

double slice_sum(const std::vector<double>& pnl, std::size_t begin, std::size_t end) {
    double sum = 0.0;
    for (std::size_t i = begin; i < end; ++i) {
        sum += pnl[i];
    }
    return sum;
}

double parallel_sum(const std::vector<double>& pnl, std::size_t slices) {
    const std::size_t n = pnl.size();
    std::vector<std::future<double>> parts;
    for (std::size_t k = 0; k < slices; ++k) {  // slice k is always [n*k/slices, n*(k+1)/slices)
        parts.push_back(std::async(std::launch::async, slice_sum, std::cref(pnl), n * k / slices, n * (k + 1) / slices));
    }
    double total = 0.0;
    for (std::future<double>& part : parts) {
        total += part.get();  // in slice order, never in the order they finish
    }
    return total;
}

double serial_sum(const std::vector<double>& pnl, std::size_t slices) {
    const std::size_t n = pnl.size();
    double total = 0.0;
    for (std::size_t k = 0; k < slices; ++k) {
        total += slice_sum(pnl, n * k / slices, n * (k + 1) / slices);
    }
    return total;
}

int main() {
    std::mt19937_64 rng(2024);  // the standard fixes its raw output for a seed
    std::vector<double> pnl(1000000);
    long long cents = 0;  // the exact total, kept in integer cents
    for (double& x : pnl) {
        const long long c = static_cast<long long>(rng() % 200001) - 100000;  // -1000.00 to 1000.00
