    std::cout << "16 slices, 16 threads: " << parallel << '\n';
    std::cout << "16 slices, 1 thread:   " << serial_sum(pnl, 16) << '\n';
    std::cout << "5 more runs identical: " << repeatable << '\n';
    std::cout << "1 slice:  " << slice_sum(pnl, 0, pnl.size()) << '\n';
    std::cout << "8 slices: " << serial_sum(pnl, 8) << '\n';
    std::cout << std::fixed << std::setprecision(2) << "exact:    " << cents / 100.0 << '\n';
    return 0;
}

