#include <future>
#include <iomanip>
#include <iostream>
#include <random>
#include <vector>

struct Trade {
    double px;
    long long qty;
};

struct Partial {
    double notional = 0.0;
    long long qty = 0;
};

Partial slice_totals(const std::vector<Trade>& trades, std::size_t begin, std::size_t end) {
    Partial p;
    for (std::size_t i = begin; i < end; ++i) {
        p.notional += trades[i].px * trades[i].qty;
        p.qty += trades[i].qty;
    }
    return p;
}

Partial serial_totals(const std::vector<Trade>& trades, std::size_t slices) {
    const std::size_t n = trades.size();
    Partial total;
    for (std::size_t k = 0; k < slices; ++k) {
        const Partial p = slice_totals(trades, n * k / slices, n * (k + 1) / slices);
        total.notional += p.notional;
        total.qty += p.qty;
    }
    return total;
}

Partial parallel_totals(const std::vector<Trade>& trades, std::size_t slices) {
    const std::size_t n = trades.size();
    std::vector<std::future<Partial>> parts;
    for (std::size_t k = 0; k < slices; ++k) {
        parts.push_back(std::async(std::launch::async, slice_totals, std::cref(trades), n * k / slices, n * (k + 1) / slices));
    }
    Partial total;
    for (std::future<Partial>& part : parts) {
        const Partial p = part.get();
        total.notional += p.notional;
        total.qty += p.qty;
    }
    return total;
}

int main() {
    std::size_t n = 0;
    std::size_t slices = 0;
    unsigned long long seed = 0;
    std::cin >> n >> slices >> seed;
    std::mt19937_64 rng(seed);
    std::vector<Trade> trades(n);
    for (Trade& t : trades) {
        t.px = static_cast<long long>(10000 + rng() % 500) / 100.0;  // 100.00 to 104.99
        t.qty = static_cast<long long>(1 + rng() % 1000);
    }
    const Partial parallel = parallel_totals(trades, slices);
    const Partial serial = serial_totals(trades, slices);
    std::cout << "qty: " << parallel.qty << '\n';
    std::cout << std::fixed << std::setprecision(6) << "vwap: " << parallel.notional / parallel.qty << '\n';
    std::cout << "parallel == one thread: " << (parallel.notional == serial.notional ? "yes" : "no") << '\n';
    return 0;
}
